export type SoPeriodType = 'daily_packaging' | 'weekly' | 'monthly';
export type SoStatus    = 'draft' | 'submitted' | 'approved' | 'rejected';

export interface StockOpname {
  soId: number; branchId: number; branchName: string; branchCode: string;
  branchType: 'OUTLET' | 'HUB WH' | 'HUB CK';
  periodType: SoPeriodType; soDate: string; periodLabel: string;
  totalValue: number; varianceValue: number;
  status: SoStatus; submittedBy: string; approvedBy: string | null;
  createdAt: string; updatedAt: string;
}

export interface StockOpnameDetail {
  detailId: number; soId: number;
  productCode: string; productName: string;
  categoryName: string; subCategoryName: string; uomName: string;
  beginningBalance: number; mobilitas: number; selfPickup: number;
  transferIn: number; salesMenu: number; nonSales: number;
  wasteQty: number; transferOut: number;
  balanceStock: number;
  actualStock: number;
  varianceQty: number;
  varianceValue: number;
  unitPrice: number; notes: string;
}

