function makeDetails(soId: number, products: typeof PACKAGING_PRODUCTS): StockOpnameDetail[] {
  return products.map((p, i) => {
    const beg = Math.floor(Math.random() * 50) + 10;
    const mob = Math.floor(Math.random() * 10);
    const sp  = Math.floor(Math.random() * 5);
    const ti  = Math.floor(Math.random() * 8);
    const sal = Math.floor(Math.random() * 30) + 5;
    const ns  = Math.floor(Math.random() * 3);
    const was = Math.floor(Math.random() * 5);
    const to  = Math.floor(Math.random() * 5);
    const balance = beg + mob + sp + ti - sal - ns - was - to;
    const actual = balance + Math.floor(Math.random() * 6) - 3;
    const varQty = actual - balance;
    return {
      detailId: soId * 100 + i,
      soId,
      productCode: p.productCode,
      productName: p.productName,
      categoryName: p.categoryName,
      subCategoryName: p.subCategoryName,
      uomName: p.uomName,
      beginningBalance: beg,
      mobilitas: mob,
      selfPickup: sp,
      transferIn: ti,
      salesMenu: sal,
      nonSales: ns,
      wasteQty: was,
      transferOut: to,
      balanceStock: balance,
      actualStock: actual,
      varianceQty: varQty,
      varianceValue: varQty * p.unitPrice,
      unitPrice: p.unitPrice,
      notes: varQty !== 0 ? 'Selisih' : '',
    };
  });
}

