export type WasteStatus = 'draft' | 'submitted' | 'approved' | 'rejected';
export type WasteReason = 'expired' | 'damaged' | 'spill' | 'other';

export interface WasteRecord {
  wasteId: number; branchId: number; branchName: string; branchCode: string;
  branchType: 'OUTLET' | 'HUB WH' | 'HUB CK';
  wasteDate: string; periodLabel: string;
  totalValue: number; totalQty: number;
  status: WasteStatus; submittedBy: string; approvedBy: string | null;
  notes: string; createdAt: string; updatedAt: string;
}

export interface WasteDetail {
  detailId: number; wasteId: number;
  productCode: string; productName: string;
  categoryName: string; uomName: string;
  qty: number; unitPrice: number; totalValue: number;
  reason: WasteReason; notes: string;
}

